-- ########## 05 coach <-> athlete chat  (sql/coach-chat.sql) ##########

create table if not exists coach_chat (
  id           uuid primary key default gen_random_uuid(),
  grant_id     uuid not null references share_grants(id) on delete cascade,
  author_role  text not null check (author_role in ('athlete', 'coach')),
  text         text not null check (char_length(text) between 1 and 4000),
  created_at   timestamptz not null default now()
);
create index if not exists idx_coach_chat_grant on coach_chat(grant_id, created_at);

alter table coach_chat enable row level security;
drop policy if exists "owner coach_chat" on coach_chat;
create policy "owner coach_chat" on coach_chat
  for all using (is_project_owner()) with check (is_project_owner());

create or replace function get_coach_chat(p_token text)
returns setof coach_chat
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_id uuid;
begin
  v_id := validate_share_token(p_token);
  if v_id is null then return; end if;
  return query
    select * from (
      select * from coach_chat where grant_id = v_id order by created_at desc limit 500
    ) last500 order by created_at;
end;
$$;

create or replace function add_coach_chat(p_token text, p_text text)
returns coach_chat
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_id uuid;
  v_row coach_chat;
begin
  v_id := validate_share_token(p_token);
  if v_id is null then raise exception 'invalid or revoked token'; end if;
  insert into coach_chat (grant_id, author_role, text)
  values (v_id, 'coach', trim(p_text))
  returning * into v_row;
  return v_row;
end;
$$;

create or replace function delete_coach_chat(p_token text, p_id uuid)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_id uuid;
begin
  v_id := validate_share_token(p_token);
  if v_id is null then raise exception 'invalid or revoked token'; end if;
  delete from coach_chat where id = p_id and grant_id = v_id and author_role = 'coach';
end;
$$;

grant execute on function get_coach_chat(text) to anon, authenticated;
grant execute on function add_coach_chat(text, text) to anon, authenticated;
grant execute on function delete_coach_chat(text, uuid) to anon, authenticated;

notify pgrst, 'reload schema';

-- ########## 06 coach token <-> messenger link  (sql/coach-chat-link.sql) ##########

alter table project_settings add column if not exists chat_user_id text;
alter table project_settings add column if not exists chat_nickname text;
alter table share_grants add column if not exists coach_chat_user_id text;
alter table share_grants add column if not exists coach_chat_nickname text;

create or replace function link_coach_chat(p_token text, p_chat_user_id text, p_nickname text)
returns table(athlete_chat_user_id text, athlete_nickname text)
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_id uuid;
begin
  v_id := validate_share_token(p_token);
  if v_id is null then
    return;
  end if;
  update share_grants
     set coach_chat_user_id = nullif(trim(coalesce(p_chat_user_id, '')), ''),
         coach_chat_nickname = left(trim(coalesce(p_nickname, '')), 60)
   where id = v_id;
  return query
    select ps.chat_user_id, ps.chat_nickname
    from project_settings ps
    where ps.chat_user_id is not null
    limit 1;
end;
$$;

grant execute on function link_coach_chat(text, text, text) to anon, authenticated;


-- ============================== final check ==============================
select 'table' as kind, n as name, exists (select 1 from information_schema.tables
       where table_schema = 'public' and table_name = n) as present
from unnest(array['project_settings', 'target_faces', 'exercise_templates', 'training_packages', 'exercises', 'file_assets', 'photo_import_jobs', 'shots', 'remote_athlete_sources', 'archived_packages', 'share_grants', 'share_events', 'comments', 'training_notes', 'ai_conversation_summaries', 'notes', 'keepalive_log', 'table_docs', 'tasks', 'task_stages', 'task_steps', 'task_clarifications', 'task_runs', 'task_run_steps', 'task_shots', 'task_series_notes', 'task_events', 'task_reports', 'task_devices', 'coach_chat']) as n
union all
select 'function', n, exists (select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace
       where s.nspname = 'public' and p.proname = n)
from unnest(array['list_public_tables', 'validate_share_token', 'get_share_policy', 'get_shared_table', 'coach_create_task', 'coach_get_tasks', 'coach_delete_task', 'athlete_submit_run', 'get_coach_chat', 'add_coach_chat']) as n
order by 1, 3, 2;
